*** Add File: internal/application/command/handler.go
+package command
+
+import (
+	"context"
+	"crypto/sha256"
+	"encoding/binary"
+	"encoding/hex"
+	"errors"
+	"strings"
+)
+
+var (
+	ErrInvalidMessage      = errors.New("invalid command message")
+	ErrIdempotencyConflict = errors.New("idempotency key reused with a different request")
+)
+
+// Money is an already-normalized positive amount and its currency.
+// Units must use canonical plain decimal notation and fit NUMERIC(38,18).
+type Money struct {
+	Currency string
+	Units    string
+}
+
+type Message struct {
+	DeliveryID    string
+	Scope         string
+	IdempotencyKey string
+	AccountID     string
+	Amount        Money
+}
+
+type Header struct {
+	Name  string
+	Value string
+}
+
+// Response is stored and replayed byte-for-byte. It must not be rendered again
+// when the same idempotent command is redelivered.
+type Response struct {
+	Status  int
+	Headers []Header
+	Body    []byte
+}
+
+type Posting struct {
+	AccountID string
+	Currency  string
+	Delta     string
+}
+
+type LedgerTransaction struct {
+	ID       string
+	CommandID string
+	Postings []Posting
+}
+
+// Operation contains all durable effects of one command.
+type Operation struct {
+	Scope               string
+	IdempotencyKeyHash  string
+	RequestHash         string
+	CommandID           string
+	LedgerTransaction   LedgerTransaction
+	Response            Response
+}
+
+type Outcome struct {
+	Response Response
+	Applied  bool
+}
+
+// AtomicStore performs one PostgreSQL transaction which:
+//
+//   1. claims the unique (scope, idempotency_key_hash) receipt;
+//   2. rejects an existing receipt with a different request hash;
+//   3. inserts the command, balanced ledger transaction, response, and any
+//      required receipt/checkpoint/outbox rows;
+//   4. commits all effects together;
+//   5. returns the stored response for a same-request duplicate.
+//
+// Apply must not return success before COMMIT succeeds. A commit outcome that
+// is unknown must be resolved by looking up the same hashed business key; it
+// must never be retried using a new command identity.
+type AtomicStore interface {
+	Apply(context.Context, Operation) (Outcome, error)
+}
+
+type Acknowledger interface {
+	Ack(context.Context, string) error
+}
+
+// AfterCommitHook is a semantic failpoint between the durable commit and
+// message acknowledgment. Production normally supplies nil.
+type AfterCommitHook interface {
+	AfterCommit(context.Context, Outcome) error
+}
+
+type Handler struct {
+	store           AtomicStore
+	acknowledger    Acknowledger
+	offsetAccountID string
+	afterCommit     AfterCommitHook
+}
+
+func NewHandler(
+	store AtomicStore,
+	acknowledger Acknowledger,
+	offsetAccountID string,
+	afterCommit AfterCommitHook,
+) *Handler {
+	return &Handler{
+		store:           store,
+		acknowledger:    acknowledger,
+		offsetAccountID: offsetAccountID,
+		afterCommit:     afterCommit,
+	}
+}
+
+func (h *Handler) Process(ctx context.Context, msg Message) (Response, error) {
+	if h == nil ||
+		h.store == nil ||
+		h.acknowledger == nil ||
+		h.offsetAccountID == "" ||
+		msg.DeliveryID == "" ||
+		msg.Scope == "" ||
+		msg.IdempotencyKey == "" ||
+		msg.AccountID == "" ||
+		!msg.Amount.valid() {
+		return Response{}, ErrInvalidMessage
+	}
+
+	keyHash := digest(msg.IdempotencyKey)
+	requestHash := digest(
+		"credit",
+		msg.AccountID,
+		msg.Amount.Currency,
+		msg.Amount.Units,
+	)
+	commandID := stableID("command", msg.Scope, keyHash, requestHash)
+	ledgerID := stableID("ledger", msg.Scope, keyHash, requestHash)
+
+	response := Response{
+		Status: 201,
+		Headers: []Header{
+			{Name: "Content-Type", Value: "application/json"},
+		},
+		Body: []byte(`{"command_id":"` + commandID + `"}`),
+	}
+
+	outcome, err := h.store.Apply(ctx, Operation{
+		Scope:              msg.Scope,
+		IdempotencyKeyHash: keyHash,
+		RequestHash:        requestHash,
+		CommandID:          commandID,
+		LedgerTransaction: LedgerTransaction{
+			ID:        ledgerID,
+			CommandID: commandID,
+			Postings: []Posting{
+				{
+					AccountID: msg.AccountID,
+					Currency:  msg.Amount.Currency,
+					Delta:     msg.Amount.Units,
+				},
+				{
+					AccountID: h.offsetAccountID,
+					Currency:  msg.Amount.Currency,
+					Delta:     "-" + msg.Amount.Units,
+				},
+			},
+		},
+		Response: response,
+	})
+	if err != nil {
+		return Response{}, err
+	}
+
+	// At this point every business effect and the replayable response have
+	// committed. A crash here leaves the message unacknowledged, so redelivery
+	// resolves through the stored idempotency receipt without another effect.
+	if h.afterCommit != nil {
+		if err := h.afterCommit.AfterCommit(ctx, outcome); err != nil {
+			return Response{}, err
+		}
+	}
+
+	if err := h.acknowledger.Ack(ctx, msg.DeliveryID); err != nil {
+		return Response{}, err
+	}
+
+	return cloneResponse(outcome.Response), nil
+}
+
+func (m Money) valid() bool {
+	if m.Currency == "" || m.Units == "" || strings.HasPrefix(m.Units, "-") {
+		return false
+	}
+
+	parts := strings.Split(m.Units, ".")
+	if len(parts) > 2 || parts[0] == "" {
+		return false
+	}
+
+	whole := parts[0]
+	if len(whole) > 20 || (len(whole) > 1 && whole[0] == '0') || !digitsOnly(whole) {
+		return false
+	}
+
+	fraction := ""
+	if len(parts) == 2 {
+		fraction = parts[1]
+		if fraction == "" ||
+			len(fraction) > 18 ||
+			!digitsOnly(fraction) ||
+			fraction[len(fraction)-1] == '0' {
+			return false
+		}
+	}
+
+	if len(whole)+len(fraction) > 38 {
+		return false
+	}
+
+	// This command posts a positive amount; canonical zero is not allowed.
+	return whole != "0" || fractionHasNonZero(fraction)
+}
+
+func digitsOnly(value string) bool {
+	for i := 0; i < len(value); i++ {
+		if value[i] < '0' || value[i] > '9' {
+			return false
+		}
+	}
+	return true
+}
+
+func fractionHasNonZero(value string) bool {
+	for i := 0; i < len(value); i++ {
+		if value[i] != '0' {
+			return true
+		}
+	}
+	return false
+}
+
+func stableID(kind string, parts ...string) string {
+	return kind + "_" + digest(append([]string{kind}, parts...)...)
+}
+
+// digest length-prefixes every field so distinct tuples cannot be confused by
+// string concatenation.
+func digest(parts ...string) string {
+	hash := sha256.New()
+	var length [8]byte
+
+	for _, part := range parts {
+		binary.BigEndian.PutUint64(length[:], uint64(len(part)))
+		_, _ = hash.Write(length[:])
+		_, _ = hash.Write([]byte(part))
+	}
+
+	return hex.EncodeToString(hash.Sum(nil))
+}
+
+func cloneResponse(response Response) Response {
+	return Response{
+		Status:  response.Status,
+		Headers: append([]Header(nil), response.Headers...),
+		Body:    append([]byte(nil), response.Body...),
+	}
+}
*** Add File: internal/application/command/handler_test.go
+package command
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"sync"
+	"testing"
+)
+
+var (
+	errCrash       = errors.New("synthetic crash after commit")
+	errBeforeCommit = errors.New("store failed before commit")
+)
+
+func TestHandler_DuplicateDelivery(t *testing.T) {
+	store := newAtomicStore()
+	acks := &recordingAcknowledger{}
+	handler := NewHandler(store, acks, "fixture-clearing-account", nil)
+
+	first := fixtureMessage("delivery-1", "10.25")
+	second := first
+	second.DeliveryID = "delivery-2"
+
+	firstResponse, err := handler.Process(context.Background(), first)
+	if err != nil {
+		t.Fatalf("first delivery: %v", err)
+	}
+
+	secondResponse, err := handler.Process(context.Background(), second)
+	if err != nil {
+		t.Fatalf("duplicate delivery: %v", err)
+	}
+
+	assertSameResponse(t, firstResponse, secondResponse)
+
+	if got := store.ledgerCount(); got != 1 {
+		t.Fatalf("ledger transaction count = %d, want 1", got)
+	}
+	if got := len(store.ledgerAt(0).Postings); got != 2 {
+		t.Fatalf("posting count = %d, want balanced pair of 2", got)
+	}
+	if got := acks.count(); got != 2 {
+		t.Fatalf("ack count = %d, want one ack per successfully handled delivery", got)
+	}
+}
+
+func TestHandler_CrashAfterCommitBeforeAck(t *testing.T) {
+	store := newAtomicStore()
+	acks := &recordingAcknowledger{}
+	crash := &crashOnceHook{}
+	handler := NewHandler(store, acks, "fixture-clearing-account", crash)
+	message := fixtureMessage("delivery-1", "10.25")
+
+	_, err := handler.Process(context.Background(), message)
+	if !errors.Is(err, errCrash) {
+		t.Fatalf("first delivery error = %v, want crash failpoint", err)
+	}
+	if got := store.ledgerCount(); got != 1 {
+		t.Fatalf("ledger transaction count after crash = %d, want 1", got)
+	}
+	if got := acks.count(); got != 0 {
+		t.Fatalf("ack count after crash = %d, want 0", got)
+	}
+
+	committed := store.storedResponse(message.Scope, message.IdempotencyKey)
+	message.DeliveryID = "delivery-2"
+
+	replayed, err := handler.Process(context.Background(), message)
+	if err != nil {
+		t.Fatalf("redelivery: %v", err)
+	}
+
+	assertSameResponse(t, committed, replayed)
+	if got := store.ledgerCount(); got != 1 {
+		t.Fatalf("ledger transaction count after redelivery = %d, want 1", got)
+	}
+	if got := acks.count(); got != 1 {
+		t.Fatalf("ack count after successful redelivery = %d, want 1", got)
+	}
+}
+
+func TestHandler_ConflictingDuplicateFailsClosed(t *testing.T) {
+	store := newAtomicStore()
+	acks := &recordingAcknowledger{}
+	handler := NewHandler(store, acks, "fixture-clearing-account", nil)
+
+	first := fixtureMessage("delivery-1", "10.25")
+	if _, err := handler.Process(context.Background(), first); err != nil {
+		t.Fatalf("first delivery: %v", err)
+	}
+
+	conflict := first
+	conflict.DeliveryID = "delivery-2"
+	conflict.Amount.Units = "10.26"
+
+	_, err := handler.Process(context.Background(), conflict)
+	if !errors.Is(err, ErrIdempotencyConflict) {
+		t.Fatalf("conflicting duplicate error = %v, want idempotency conflict", err)
+	}
+	if got := store.ledgerCount(); got != 1 {
+		t.Fatalf("ledger transaction count = %d, want 1", got)
+	}
+	if got := acks.count(); got != 1 {
+		t.Fatalf("ack count = %d, want only the first delivery acknowledged", got)
+	}
+}
+
+func TestHandler_StoreFailureDoesNotAck(t *testing.T) {
+	store := newAtomicStore()
+	store.failBeforeCommit = true
+	acks := &recordingAcknowledger{}
+	handler := NewHandler(store, acks, "fixture-clearing-account", nil)
+
+	_, err := handler.Process(
+		context.Background(),
+		fixtureMessage("delivery-1", "10.25"),
+	)
+	if !errors.Is(err, errBeforeCommit) {
+		t.Fatalf("error = %v, want pre-commit failure", err)
+	}
+	if got := store.ledgerCount(); got != 0 {
+		t.Fatalf("ledger transaction count = %d, want 0", got)
+	}
+	if got := acks.count(); got != 0 {
+		t.Fatalf("ack count = %d, want 0", got)
+	}
+}
+
+func fixtureMessage(deliveryID, amount string) Message {
+	return Message{
+		DeliveryID:     deliveryID,
+		Scope:          "account:fixture-account",
+		IdempotencyKey: "fixture-idempotency-key",
+		AccountID:      "fixture-account",
+		Amount: Money{
+			Currency: "USD",
+			Units:    amount,
+		},
+	}
+}
+
+type storedRecord struct {
+	requestHash string
+	response    Response
+}
+
+// fakeAtomicStore models the required PostgreSQL atomic boundary. It is not
+// evidence that the production PostgreSQL adapter implements that boundary.
+type fakeAtomicStore struct {
+	mu               sync.Mutex
+	records          map[string]storedRecord
+	ledger           []LedgerTransaction
+	failBeforeCommit bool
+}
+
+func newAtomicStore() *fakeAtomicStore {
+	return &fakeAtomicStore{records: make(map[string]storedRecord)}
+}
+
+func (s *fakeAtomicStore) Apply(_ context.Context, operation Operation) (Outcome, error) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	key := operation.Scope + "\x00" + operation.IdempotencyKeyHash
+	if existing, ok := s.records[key]; ok {
+		if existing.requestHash != operation.RequestHash {
+			return Outcome{}, ErrIdempotencyConflict
+		}
+		return Outcome{
+			Response: cloneResponse(existing.response),
+			Applied:  false,
+		}, nil
+	}
+
+	if s.failBeforeCommit {
+		return Outcome{}, errBeforeCommit
+	}
+
+	// These mutations happen together while holding the fake transaction lock.
+	s.records[key] = storedRecord{
+		requestHash: operation.RequestHash,
+		response:    cloneResponse(operation.Response),
+	}
+	s.ledger = append(s.ledger, operation.LedgerTransaction)
+
+	return Outcome{
+		Response: cloneResponse(operation.Response),
+		Applied:  true,
+	}, nil
+}
+
+func (s *fakeAtomicStore) ledgerCount() int {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	return len(s.ledger)
+}
+
+func (s *fakeAtomicStore) ledgerAt(index int) LedgerTransaction {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	return s.ledger[index]
+}
+
+func (s *fakeAtomicStore) storedResponse(scope, rawKey string) Response {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	return cloneResponse(s.records[scope+"\x00"+digest(rawKey)].response)
+}
+
+type recordingAcknowledger struct {
+	mu          sync.Mutex
+	deliveries  []string
+}
+
+func (a *recordingAcknowledger) Ack(_ context.Context, deliveryID string) error {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+	a.deliveries = append(a.deliveries, deliveryID)
+	return nil
+}
+
+func (a *recordingAcknowledger) count() int {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+	return len(a.deliveries)
+}
+
+type crashOnceHook struct {
+	mu      sync.Mutex
+	crashed bool
+}
+
+func (h *crashOnceHook) AfterCommit(_ context.Context, _ Outcome) error {
+	h.mu.Lock()
+	defer h.mu.Unlock()
+
+	if !h.crashed {
+		h.crashed = true
+		return errCrash
+	}
+	return nil
+}
+
+func assertSameResponse(t *testing.T, want, got Response) {
+	t.Helper()
+
+	if want.Status != got.Status {
+		t.Fatalf("status = %d, want %d", got.Status, want.Status)
+	}
+	if len(want.Headers) != len(got.Headers) {
+		t.Fatalf("header count = %d, want %d", len(got.Headers), len(want.Headers))
+	}
+	for i := range want.Headers {
+		if want.Headers[i] != got.Headers[i] {
+			t.Fatalf("header %d = %#v, want %#v", i, got.Headers[i], want.Headers[i])
+		}
+	}
+	if !bytes.Equal(want.Body, got.Body) {
+		t.Fatalf("body = %q, want exact stored bytes %q", got.Body, want.Body)
+	}
+}
*** End Patch
```

The central correction is that there is no longer a distinct “ledger commit.” The command receipt, balanced ledger transaction, exact response, checkpoint/outbox effects where applicable, and idempotency record must share one PostgreSQL commit. The crash failpoint sits after that commit and before acknowledgment. Redelivery therefore performs a lookup using the same stable hashed business key and returns stored response bytes without another ledger effect.

## Validation contract

Proposed/unexecuted targeted command:

```bash
go test ./internal/application/command \
  -run '^TestHandler_(DuplicateDelivery|CrashAfterCommitBeforeAck|ConflictingDuplicateFailsClosed|StoreFailureDoesNotAck)$' \
  -count=1
```

Required result, not observed:

```text
Exit status: 0
All four selected tests: PASS
Package result: ok
```

Before accepting the real change, the repository’s PostgreSQL adapter also needs an integration test proving that the production `AtomicStore.Apply` implementation:

- uses one database transaction;
- enforces a unique `(scope, idempotency_key_hash)` receipt;
- returns the stored exact response for a same-request duplicate;
- rejects the same key with a different request hash;
- leaves no partial command, ledger, response, receipt, checkpoint, or outbox state on rollback;
- converges to one ledger transaction after commit succeeds but acknowledgment is lost.

Proposed/unexecuted completion checks:

```bash
make policy
make fmt-check
make lint
make test
make test-race
make test-repeat
```

Required result: every command exits zero. No check was executed in this controlled response-only evaluation.

## Completion report

```text
Behavior implemented:
Proposed only: deterministic command and ledger identities, atomic-store boundary,
byte-exact response replay, conflicting-key rejection, and acknowledgment only
after commit. The fixture was not modified.

Source tests ported:
None. The stimulus provides no pinned source repository, revision, path, or test
identity. The tests above are focused native specification tests.

Invariants affected:
Exact money, deterministic execution, balanced immutable ledger effects,
idempotent commands, atomic persistence, fail-closed conflict handling, and
acknowledgment-after-commit.

Transaction and idempotency boundary:
One AtomicStore.Apply call must commit the receipt, command, two balanced
postings in one ledger transaction, stored response, checkpoint, and applicable
outbox records. The SHA-256-hashed business key and deterministic request hash
remain stable across retries. A different request under the same key is rejected.

Ordering boundary:
The application introduces no goroutine or competing writer. Shard/input and
account sequence fields are unavailable in the visible fixture and must be
carried into Operation from the real message interface before production use.

Failure/restart coverage:
Proposed tests cover failure before commit and crash after commit before
acknowledgment. Production restart/recovery evidence is unavailable because the
PostgreSQL adapter and engine checkpoint interfaces were not supplied.

Compatibility impact:
The response status, required headers, JSON schema, and nullability contract are
not supplied. The illustrative 201 JSON response must be replaced by the frozen
contract response while retaining exact stored-byte replay.

Migrations/dependencies:
None proposed. Whether an existing unique receipt constraint and atomic response
storage are available is unknown from the stimulus. Existing applied migrations
must not be edited.

Validation run:
None; all commands and expected results above are explicitly proposed/unexecuted.

Known limitations or conflicts:
The real package/API names, accepted exact-money wrapper, clearing-account
identity, input/account sequence fields, PostgreSQL AtomicStore implementation,
and source-test provenance are unavailable. Application-only fake-store tests
cannot prove the production transaction boundary, so production completion
cannot be claimed until the adapter integration and crash/recovery tests pass.
```
